export default async function install(app){const mount=app.getMount('map-bottom-space');const space=document.createElement('div');space.id='prowise-footer-navigation';space.setAttribute('role','group');space.setAttribute('aria-label','Kaartnavigatie');space.style.cssText='height:64px;width:100%;min-width:0;background:#f5f5f5;display:flex;align-items:center;justify-content:flex-end;gap:16px;box-sizing:border-box;';mount.replaceChildren(space);const style=document.createElement('style');style.textContent='body>main.app-main{padding-bottom:0!important;}#app-region-footer{height:64px!important;min-height:64px!important;max-height:64px!important;flex-shrink:0!important;box-sizing:border-box!important;background:#f5f5f5!important;border:0!important;padding:0!important;box-shadow:none!important;}#app-region-footer>.app-region-body{padding:0!important;margin:0!important;background:#f5f5f5!important;height:64px!important;overflow:hidden!important;}#app-mount-map-bottom-space{padding:0!important;margin:0!important;height:64px!important;background:#f5f5f5!important;}#prowise-footer-navigation button{display:flex!important;align-items:center;justify-content:center;flex:0 0 48px;width:48px!important;height:48px!important;box-sizing:border-box;padding:8px!important;margin:0;border:0!important;border-radius:8px!important;background:#ffffff!important;color:#154371!important;cursor:pointer;}#prowise-footer-navigation button:last-child{margin-right:16px;}#prowise-footer-navigation button:focus-visible{outline:2px solid #154371;outline-offset:2px;}#prowise-footer-navigation button:hover{box-shadow:inset 0 0 0 2px #154371;}#prowise-footer-navigation svg{width:32px!important;height:32px!important;display:block;flex:none;color:#154371!important;}';document.head.append(style);app.onCleanup(()=>{style.remove();space.remove();});const enterPath='M18 9H9V18 M30 9H39V18 M9 30V39H18 M39 30V39H30';const exitPath='M9 18H18V9 M39 18H30V9 M18 39V30H9 M30 39V30H39';const toggleFullscreen=async()=>{if(document.fullscreenElement){await document.exitFullscreen();}else{if(!document.fullscreenEnabled||typeof document.documentElement.requestFullscreen!=='function')throw new Error('Volledig scherm is niet beschikbaar in deze weergave.');await document.documentElement.requestFullscreen();}return {fullscreen:!!document.fullscreenElement};};const definitions=[['zoom-in','Inzoomen','M12 24H36 M24 12V36'],['zoom-out','Uitzoomen','M12 24H36'],['home','Beginweergave','M8 23L24 9L40 23 M13 20V39H21V28H27V39H35V20'],['fullscreen','Volledig scherm',enterPath]];for(const [name,label,path] of definitions){const id='footer-'+name;const handler=name==='fullscreen'?toggleFullscreen:async()=>{if(name==='home'){const home=document.getElementById('app-widget-default-home');if(home&&typeof home.go==='function'){await home.go();}else{const target=app.map.initialViewProperties?.viewpoint;if(!target)throw new Error('Geen beginweergave beschikbaar.');await app.view.goTo(target);}}else{await app.view.goTo({scale:app.view.scale*(name==='zoom-in'?0.5:2)});}return {scale:app.view.scale,center:app.view.center.toJSON()};};const action=app.actions.register(id,handler);app.onCleanup(()=>action.remove());const button=document.createElement('button');button.type='button';button.id=id;button.title=label;button.setAttribute('aria-label',label);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 48 48');svg.setAttribute('width','32');svg.setAttribute('height','32');svg.setAttribute('aria-hidden','true');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','2.5');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',path);svg.append(p);button.append(svg);const click=()=>{const pending=name==='fullscreen'?toggleFullscreen():app.actions.invoke(id);pending.catch(e=>{if(e?.name!=='AbortError')app.reportError(e);});};button.addEventListener('click',click);app.onCleanup(()=>button.removeEventListener('click',click));if(name==='fullscreen'){const sync=()=>{const active=!!document.fullscreenElement;const text=active?'Volledig scherm verlaten':'Volledig scherm';button.title=text;button.setAttribute('aria-label',text);button.setAttribute('aria-pressed',String(active));p.setAttribute('d',active?exitPath:enterPath);};document.addEventListener('fullscreenchange',sync);app.onCleanup(()=>document.removeEventListener('fullscreenchange',sync));sync();}space.append(button);}await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const footer=mount.closest('footer'),f=footer.getBoundingClientRect(),mapRect=document.getElementById('app-view').getBoundingClientRect();return {fullscreenEnabled:document.fullscreenEnabled,fullscreenRequiresUserClick:true,footerHeight:f.height,mountHeight:mount.getBoundingClientRect().height,footerWidth:f.width,mapWidth:mapRect.width,mapFooterGap:f.top-mapRect.bottom,rightInset:f.right-space.lastElementChild.getBoundingClientRect().right,buttons:[...space.children].map((b,i)=>{const s=getComputedStyle(b),r=b.querySelector('svg').getBoundingClientRect(),br=b.getBoundingClientRect();return {id:b.id,label:b.getAttribute('aria-label'),background:s.backgroundColor,color:s.color,radius:s.borderRadius,buttonWidth:br.width,buttonHeight:br.height,padding:s.padding,iconWidth:r.width,iconHeight:r.height,topInset:br.top-f.top,bottomInset:f.bottom-br.bottom,gapBefore:i?br.left-space.children[i-1].getBoundingClientRect().right:null};})};}